import { load, cleanText } from "./util.js";
import type { PianoGomp } from "../../types.js";

// Parser for GOMP's ElencoPiani.aspx (the piano di studi listing). A WebForms
// grid (table#ctl00_contents_PSGrid) with columns A/A, Ultima modifica,
// Denominazione, Status, Azione; each row's detail link is the page-relative
// Composer.aspx?PS=<uuid>. Positional on purpose — the grid is generated by
// ASP.NET and its column order is stable; anything unexpected yields no rows.
// `pageUrl` is the listing's own URL, used to resolve the relative links.
export function parse(html: string, pageUrl: string): PianoGomp[] {
  const $ = load(html);
  const out: PianoGomp[] = [];
  $("table tr").each((_, tr) => {
    const cells = $(tr).find("td");
    if (cells.length < 4) return;
    const href = cells.find("a[href*='Composer.aspx?PS=']").first().attr("href");
    if (!href) return;
    out.push({
      ps: href.match(/[?&]PS=([0-9a-f-]{36})/i)?.[1] ?? null,
      aa: cleanText(cells.eq(0).text()) || null,
      ultimaModifica: cleanText(cells.eq(1).text()) || null,
      denominazione: cleanText(cells.eq(2).text()) || null,
      status: cleanText(cells.eq(3).text()) || null,
      composerUrl: new URL(href.replace(/&amp;/g, "&"), pageUrl).toString(),
    });
  });
  return out;
}
